@Component
public class PermissionApplyFlowFactory {
    private final Map<PermissionApplyType, IAbstractPermissionApplyFlow> permissionApplyByTypeMap = new ConcurrentHashMap<>();

    public void registerPermissionApply(PermissionApplyType businessType, IAbstractPermissionApplyFlow impl) {
        if (!permissionApplyByTypeMap.containsKey(businessType)) {
            permissionApplyByTypeMap.put(businessType, impl);
        }
    }
    public IAbstractPermissionApplyFlow getPermissionApplyImpl(PermissionApplyType sourceType) {
        return permissionApplyByTypeMap.get(sourceType);
    }
}

@CommonLock(prefix = "SUBMIT_FLOW_ROLE_")
public CraneFlowRespVo submitRoleFlow(@LockField String submitWorkNumber, RoleFlowSubmitVo req) {
    checkSubmitFlowReq(submitWorkNumber, req);                        // 1.校验参数
    RoleApplyFlowMessageLinkVo messageLinkVo = buildSnapshotVo(...);  // 2.构建OA快照(落库可追溯)
    PermissionApplyVO applyVO = saveApplyInfo(req, messageLinkVo);    // 3.落3张表(申请单/员工/详情)
    FlowResponse flowResponse = createOAFlow(applyVO, messageLinkVo); // 4.创建OA审批流(失败则清理脏数据)
    updatePermissionApplyId(applyVO, flowResponse);                   // 5.回写flowId
    return buildCraneFLowResp(flowResponse);
}

@CommonLock(prefix = "role_apply_op_", matchAllMarkField = true, waitTime = 5L)
@Transactional(rollbackFor = Exception.class, propagation = Propagation.NESTED)
public void openEmployeeRelationRole(@LockField String applyNumber, @LockField Long roleId, Long applyResultId, ValidTime validTime) {
    PermissionApplyResultVO result = permissionApplyResultService.fetchApplyResultById(applyResultId);
    // 状态机幂等：只有 INIT / CALLBACK_FAIL 可开通
    if (!PermissionApplyResultStatus.getCraneCanOpenStatus().contains(result.getStatus())) { return; }
    boolean success = employeeRoleService.assignRoleByFlow(employeeRoleRequest, expireTime);
    if (!success) {
        // 失败置 CALLBACK_FAIL + retry_time+1，交给 OpenRetryJob 重试，不影响外部事务提交
        permissionApplyResultService.updateApplyResultStatusAndIncreaseRetryTime(applyResultId, CALLBACK_FAIL);
    }
}

RLock lock = redissonClient.getLock(buildLockKey(lockName));
boolean locked = lock.tryLock(waitTime, -1L, timeUnit);        // leaseTime=-1 → 看门狗自动续期
if (!locked) { throw new CraneException(LOCK_ERROR, ...); }
try { return supplier.get(); }
finally { if (lock.isHeldByCurrentThread()) { lock.unlock(); } }  // 只释放自己持有的锁，防误删

for (BusinessVO businessVO : request.getBusinessVOS()) {
    futures.add(CompletableFuture.supplyAsync(() -> {
        try {
            List<RoleVO> roleVOS = employeeRoleService.fetchRoleByEmployeeAndBusiness(empNo, businessVO.getCode());
            List<EmployeePermissionVO> perms = employeePermissionService.fetchPermissionListByRequest(queryRequest);
            return new BusinessAuthorityVO(businessVO, perms, roleVOS);
        } catch (Throwable e) {
            log.error("getBusinessAuthorityVOListV2-exception, businessCode:{}", businessVO.getCode(), e);
            return null;    // 单系统失败不影响其他系统
        }
    }, ttlExecutorService));   // TtlExecutors 包装，TransmittableThreadLocal 传递上下文
}
CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).get(fetchV2TimeOut, TimeUnit.SECONDS);

Set<String> businessCodes = businessVOS.stream().map(b -> b.getCode().toUpperCase()).collect(Collectors.toSet());
List<RoleVO> allRoles = employeeRoleService.fetchRoleByEmployeeAndBusinessCodes(empNo, businessCodes);       // 角色 1 次批量
List<EmployeePermissionVO> allPerms = employeePermissionService.fetchEmployeePermissionVOList(empNo, businessCodes); // 权限 1 次批量
Map<String, List<EmployeePermissionVO>> permGroup = allPerms.stream().collect(groupingBy(EmployeePermissionVO::getBusinessCode));
Map<String, List<RoleVO>> roleGroup = allRoles.stream().collect(groupingBy(RoleVO::getBusinessCode));

private String hashKey(String employeeNumber) { return String.valueOf(Math.abs(employeeNumber.hashCode() % 256)); }
// 读：256 桶按 64 桶/批分批并行读取；写：缺失桶位填充空列表，保证 256 个桶始终完整，读侧无需判空
private List<List<String>> partitionHashKeys(List<String> allHashKey) {
    return ListUtils.partition(allHashKey, DynamicProperties.getInt("cache.allEmployee.get.partitionSize", 64));
}

public void employeeAssignPermission(EmployeeOaVo beforeVo, EmployeeOaVo afterVo) {
    if (isEntry) { employeeEntryAssignPermission(employeeVO); return; }   // 入职：关联Basic角色+建账号+分数据权限
    if (isLeave) { employeeLeaveCancelPermission(employeeVO); return; }   // 离职：全量回收
    employeeChangeAssignPermission(beforeErpVo, employeeVO);              // 调岗：事务内换部门角色
}
